public class ApprovalRequiredTool : AIFunction
{
    private readonly AIFunction _inner;
    private readonly ApprovalConfig _config;
    private readonly IApprovalService _approvalService;

    public ApprovalRequiredTool(AIFunction inner, ApprovalConfig config, IApprovalService approval)
    {
        _inner = inner;
        _config = config;
        _approvalService = approval;
    }

    protected override async Task<FunctionResult> InvokeAsync(
        FunctionArguments arguments,
        CancellationToken cancellationToken)
    {
        // Check if this tool requires approval
        if (await _config.RequiresApprovalAsync(arguments))
        {
            var approvalRequest = new ApprovalRequest
            {
                ToolName = Name,
                Arguments = arguments.ToDictionary(),
                RiskLevel = _config.RiskLevel,
                UserMessageId = GetCurrentUserId()
            };

            var approved = await _approvalService.RequestApprovalAsync(approvalRequest, cancellationToken);
            if (!approved.Approved)
            {
                return new FunctionResult($"Action blocked by user: {approved.RejectionReason}");
            }

            // Log the approval for audit trail
            await _approvalService.LogApprovalAsync(approvalRequest, approved, cancellationToken);
        }

        return await _inner.InvokeAsync(arguments, cancellationToken);
    }
}

[ApiController]
[Route("api/agent/{sessionId}/intervene")]
public class AgentInterventionController : ControllerBase
{
    private readonly IAgentSessionStore _sessions;

    [HttpPost("pause")]
    public async Task<IActionResult> Pause(string sessionId)
    {
        var session = await _sessions.GetAsync(sessionId);
        if (session == null) return NotFound();

        session.State = AgentState.Paused;
        await _sessions.UpdateAsync(session);

        // Notify connected clients via SignalR
        await _hubContext.Clients.Group(sessionId)
            .SendAsync("agent_paused", new { sessionId });

        return Ok(new { status = "paused" });
    }

    [HttpPost("override")]
    public async Task<IActionResult> Override(string sessionId, [FromBody] Intervention intervention)
    {
        var session = await _sessions.GetAsync(sessionId);
        if (session == null) return NotFound();

        // Add human instruction to the conversation
        session.Conversation.Add(new ChatMessage(ChatRole.User,
            $"[Human Override] {intervention.Instruction}"));

        // Resume with modified context
        session.PendingIntervention = intervention;
        session.State = AgentState.Running;
        await _sessions.UpdateAsync(session);

        return Ok(new { status = "resumed" });
    }
}
